(455, 21, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:23', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Các hình phẳng cơ bản:\\n- Hình vuông: có 4 cạnh bằng nhau.\\n- Hình chữ nhật: có 4 cạnh, 2 cặp cạnh đối bằng nhau.\\n- Hình tam giác: có 3 cạnh và 3 góc.\\n- Hình tròn: không có cạnh, không có góc.\\n\\nHãy quan sát các hình bên dưới để nhận biết đặc điểm riêng của từng hình.\", \"trucQuan\": {\"type\": \"hinh\", \"shapes\": [\"vuong\", \"tron\", \"tam_giac\", \"chu_nhat\"]}}'),
