(503, 65, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Phép cộng là gộp hai hay nhiều số lại với nhau để được tổng.\\n\\nVí dụ: An có 3 quả táo, mẹ cho thêm 2 quả táo nữa. Hỏi An có tất cả bao nhiêu quả táo?\\nTa lấy số táo ban đầu cộng với số táo được cho thêm: 3 + 2 = 5.\\nVậy An có tất cả 5 quả táo.\", \"trucQuan\": {\"icon\": \"?\", \"type\": \"dem_so\", \"count\": 5}}'),
