(511, 67, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Phép trừ là bớt đi một số từ một số khác để được hiệu.\\n\\nVí dụ: Bình có 5 cái kẹo, Bình ăn mất 2 cái. Hỏi Bình còn lại bao nhiêu cái kẹo?\\nTa lấy số kẹo ban đầu trừ đi số kẹo đã ăn: 5 - 2 = 3.\\nVậy Bình còn lại 3 cái kẹo.\", \"trucQuan\": {\"icon\": \"?\", \"type\": \"dem_so\", \"count\": 3}}'),
