(535, 78, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Số liền sau của một số là số lớn hơn số đó 1 đơn vị. Số liền trước là số nhỏ hơn số đó 1 đơn vị.\\n\\nVí dụ: cho số 5.\\n- Số liền sau của 5 là 5 + 1 = 6.\\n- Số liền trước của 5 là 5 - 1 = 4.\\nVậy ta có dãy: 4, 5, 6 (mỗi số sau hơn số trước 1 đơn vị).\", \"trucQuan\": {\"icon\": \"?\", \"type\": \"dem_so\", \"count\": 5}}'),
