(631, 130, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Khi so sánh hai số: số nào có nhiều chữ số hơn thì lớn hơn. Nếu số chữ số bằng nhau, ta so sánh từng hàng từ trái sang phải (hàng cao nhất trước).\\n\\nVí dụ: so sánh 7 và 4.\\n7 có 7 quả, 4 có 4 quả. Vì 7 nhiều hơn 4 nên 7 > 4.\\nDùng dấu > (lớn hơn), < (nhỏ hơn), = (bằng nhau) để viết kết quả so sánh.\", \"trucQuan\": {\"type\": \"so_sanh\", \"leftCount\": 7, \"leftLabel\": \"7\", \"rightCount\": 4, \"rightLabel\": \"4\"}}'),
(632, 130, NULL, 'Khám phá', NULL, NULL, 1, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', '{\"dapAnDungId\": \"b\"}', '{\"loai\": \"TRAC_NGHIEM\", \"video\": \"https://cdnelearning.nxbgd.vn/uploads/10752_20210601074706_[animation]-toi-la-hs-lop-2.mp4\", \"cauHoi\": \"So sánh: 661 ... 550. Điền dấu thích hợp.\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"luaChon\": [{\"id\": \"a\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai632_0\", \"noiDung\": \"=\"}, {\"id\": \"b\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai632_1\", \"noiDung\": \">\"}, {\"id\": \"c\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai632_2\", \"noiDung\": \"<\"}], \"giaoDien\": \"THE_BAI\"}');
