(695, 173, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Các khối hình cơ bản:\\n- Khối lập phương: 6 mặt đều là hình vuông bằng nhau, ví dụ con xúc xắc.\\n- Khối hộp chữ nhật: các mặt là hình chữ nhật, ví dụ hộp diêm, hộp bút.\\n- Khối cầu: tròn đều mọi phía, lăn được, ví dụ quả bóng.\\n\\nEm hãy tìm các đồ vật quanh mình có dạng những khối này.\"}'),
(696, 173, NULL, 'Khám phá', NULL, NULL, 1, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', '{\"dapAnDungId\": \"a\"}', '{\"loai\": \"TRAC_NGHIEM\", \"video\": \"https://cdnelearning.nxbgd.vn/uploads/10752_20210601074706_[animation]-toi-la-hs-lop-2.mp4\", \"cauHoi\": \"Vật nào có dạng khối lập phương (6 mặt là hình vuông bằng nhau)?\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"luaChon\": [{\"id\": \"a\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai696_0\", \"noiDung\": \"Con xúc xắc\"}, {\"id\": \"b\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai696_1\", \"noiDung\": \"Quả bóng\"}, {\"id\": \"c\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai696_2\", \"noiDung\": \"Hộp bút chì dài\"}, {\"id\": \"d\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai696_3\", \"noiDung\": \"Lon nước ngọt\"}], \"giaoDien\": \"THE_BAI\"}'),
