(743, 205, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Chu vi hình chữ nhật = (chiều dài + chiều rộng) x 2. Diện tích hình chữ nhật = chiều dài x chiều rộng. Diện tích hình vuông = cạnh x cạnh.\\n\\nVí dụ: hình chữ nhật dài 5cm, rộng 3cm.\\nChu vi = (5 + 3) x 2 = 16cm. Diện tích = 5 x 3 = 15cm².\"}'),
(744, 205, NULL, 'Khám phá', NULL, NULL, 1, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', '{\"dapAnDungId\": \"a\"}', '{\"loai\": \"TRAC_NGHIEM\", \"video\": \"https://cdnelearning.nxbgd.vn/uploads/10752_20210601074706_[animation]-toi-la-hs-lop-2.mp4\", \"cauHoi\": \"Hình chữ nhật có chiều dài 9cm, chiều rộng 3cm. Chu vi hình đó là bao nhiêu?\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"luaChon\": [{\"id\": \"a\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai744_0\", \"noiDung\": \"24\"}, {\"id\": \"b\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai744_1\", \"noiDung\": \"26\"}, {\"id\": \"c\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai744_2\", \"noiDung\": \"22\"}, {\"id\": \"d\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai744_3\", \"noiDung\": \"27\"}], \"giaoDien\": \"THE_BAI\"}'),
