(799, 238, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Bài toán giải bằng 3 bước tính: xác định các đại lượng đã cho, thực hiện các phép tính trung gian theo đúng thứ tự, rồi tính ra đáp số cuối cùng.\\n\\nVí dụ: kho có 30kg gạo, bán 10kg buổi sáng, bán thêm 5kg buổi chiều. Số gạo còn lại: 30 - 10 - 5 = 15kg.\"}'),
(800, 238, NULL, 'Khám phá', NULL, NULL, 1, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', '{\"dapAnDungId\": \"a\"}', '{\"loai\": \"TRAC_NGHIEM\", \"video\": \"https://cdnelearning.nxbgd.vn/uploads/10752_20210601074706_[animation]-toi-la-hs-lop-2.mp4\", \"cauHoi\": \"Một cửa hàng có 20 kg gạo, bán 11 kg buổi sáng và 13 kg buổi chiều. Hỏi cửa hàng còn lại bao nhiêu kg gạo?\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"luaChon\": [{\"id\": \"a\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai800_0\", \"noiDung\": \"-4\"}, {\"id\": \"b\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai800_1\", \"noiDung\": \"9\"}, {\"id\": \"c\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai800_2\", \"noiDung\": \"7\"}, {\"id\": \"d\", \"amThanh\": \"https://cdnelearning.nxbgd.vn/uploads/409_20200522101059_p16.mp3\", \"hinhAnh\": \"https://robohash.org/thebai800_3\", \"noiDung\": \"18\"}], \"giaoDien\": \"THE_BAI\"}'),
