(903, 295, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Muốn cộng (hoặc trừ) hai phân số cùng mẫu số, ta cộng (hoặc trừ) hai tử số với nhau và giữ nguyên mẫu số.\\n\\nVí dụ: 1/5 + 2/5 = (1+2)/5 = 3/5.\", \"trucQuan\": {\"tu\": 3, \"mau\": 5, \"type\": \"phan_so\"}}'),
