(919, 307, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Phân số gồm tử số (ở trên) và mẫu số (ở dưới), viết dạng tử/mẫu. Mẫu số cho biết một đơn vị được chia thành mấy phần bằng nhau, tử số cho biết đã lấy mấy phần.\\n\\nVí dụ: phân số 2/5 nghĩa là chia hình thành 5 phần bằng nhau và lấy 2 phần.\", \"trucQuan\": {\"tu\": 2, \"mau\": 5, \"type\": \"phan_so\"}}'),
