(967, 433, NULL, 'Lý thuyết', NULL, NULL, 0, 1, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Quãng đường = Vận tốc x Thời gian. Vận tốc = Quãng đường : Thời gian. Thời gian = Quãng đường : Vận tốc.\\n\\nVí dụ: xe đi với vận tốc 40km/giờ trong 2 giờ. Quãng đường đi được = 40 x 2 = 80km.\"}'),
