(999, 497, NULL, 'Lý thuyết', NULL, NULL, 0, 2, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Bài \'R r, S s\' giới thiệu vần/âm \'s\'.\\n\\nCác từ có chứa vần/âm này, ví dụ: sao, sữa, su su, sen.\\nVí dụ đọc: từ \'sao\' có chứa vần/âm \'s\'. Hãy đánh vần chậm rồi đọc trơn cả từ.\\nHãy đọc to và tìm thêm các từ khác có chứa vần/âm \'s\'.\", \"trucQuan\": {\"type\": \"tu_vung\", \"items\": [{\"word\": \"sao\", \"emoji\": \"⭐\"}, {\"word\": \"sữa\", \"emoji\": \"?\"}]}}'),
