(1039, 547, NULL, 'Lý thuyết', NULL, NULL, 0, 2, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Bài \'ươc ươt\' giới thiệu vần/âm \'uoc\'.\\n\\nCác từ có chứa vần/âm này, ví dụ: được, ướt, thước, trước.\\nVí dụ đọc: từ \'được\' có chứa vần/âm \'uoc\'. Hãy đánh vần chậm rồi đọc trơn cả từ.\\nHãy đọc to và tìm thêm các từ khác có chứa vần/âm \'uoc\'.\", \"trucQuan\": {\"type\": \"tu_vung\", \"items\": [{\"word\": \"thước\", \"emoji\": \"?\"}, {\"word\": \"ướt\", \"emoji\": \"?\"}]}}'),
