(1223, 648, NULL, 'Lý thuyết', NULL, NULL, 0, 2, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Bài \'Tuần 31\' thuộc chủ đề \'Con người Việt Nam\'.\\n\\nMột số từ ngữ thường gặp trong chủ đề này: quê hương, đất nước, cánh đồng lúa, dòng sông.\\nVí dụ: có thể dùng từ \'quê hương\' để đặt câu, ví dụ: \'Em rất thích quê hương.\'\\nHãy chú ý cách dùng dấu câu và từ ngữ phù hợp khi viết về chủ đề này.\", \"trucQuan\": {\"type\": \"tu_vung\", \"items\": [{\"word\": \"cánh đồng lúa\", \"emoji\": \"?\"}, {\"word\": \"cánh diều\", \"emoji\": \"?\"}]}}'),
