(1271, 661, NULL, 'Lý thuyết', NULL, NULL, 0, 2, 'JSON_TEXT', 'HE_THONG', NULL, NULL, 0, '2026-07-20 14:28:24', NULL, '{\"loai\": \"LY_THUYET\", \"noiDung\": \"Bài \'Tuần 9 Ôn tập giữa học kỳ 1\' thuộc chủ đề \'CỔNG TRƯỜNG RỘNG MỞ\'.\\n\\nMột số từ ngữ thường gặp trong chủ đề này: trường học, lớp học, thầy giáo, cô giáo.\\nVí dụ: có thể dùng từ \'trường học\' để đặt câu, ví dụ: \'Em rất thích trường học.\'\\nHãy chú ý cách dùng dấu câu và từ ngữ phù hợp khi viết về chủ đề này.\", \"trucQuan\": {\"type\": \"tu_vung\", \"items\": [{\"word\": \"trường học\", \"emoji\": \"?\"}, {\"word\": \"sách vở\", \"emoji\": \"?\"}]}}'),
